public class TokenProvider {
    private String accessToken;
    private Instant expiresAt;

    public synchronized String getToken() {
        if (accessToken == null || Instant.now().isAfter(expiresAt.minusSeconds(60))) {
            Response r = requestNewToken();
            accessToken = r.jsonPath().getString("access_token");
            long seconds = r.jsonPath().getLong("expires_in");
            expiresAt = Instant.now().plusSeconds(seconds);
        }
        return accessToken;
    }
}

